window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ddf17676f44598a8"]={"versions": [{"id": "FIG-ddf17676f44598a8", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR-Klassik-Plattform zur Veranschaulichung des Gesamtaufbaus eines Steuergeräts (ECU). Das Diagramm gliedert die Software in drei vertikale Hauptebenen über der zugrundeliegenden ECU-Hardware: die AUTOSAR Software (Anwendungsschicht), die AUTOSAR Runtime Environment (RTE) als Vermittlungsschicht und die Basis-Software (Basic Software, BSW). Linksseitig befindet sich eine Legende zu Komponententypen, Schnittstellenkategorien (Interface, ECU Firmware, Standard Software) und API-Klassifikationen (API 1, API 2, API 3).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Komponenten und Schnittstellenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software (Applikationsebene):</strong> Enthält diskrete Software-Komponenten (SW-Cs) wie <code>Application Software Component</code>, <code>Actuator Software Component</code> und <code>Sensor Software Component</code>. Jede Komponente besitzt an ihrer Unterkante ein <code>AUTOSAR Interface</code>.</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Horizontal durchgängige Middleware-Schicht, die die Anwendungs-Software von der Basis-Software entkoppelt.</li>\n<li><strong>Basic Software (BSW):</strong> Gegliedert in funktionale Säulen/Stapel:</li>\n<li><code>Operating System</code> mit <code>Standardized Interface</code> zur RTE und einer vertikalen <code>Standardized Interface</code>-Flanke zur internen BSW-Interaktion.</li>\n<li><code>Services</code> mit oberem <code>Standardized AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Communication</code> mit oberem und unterem <code>Standardized Interface</code>.</li>\n<li><code>ECU Abstraction</code> mit oberem <code>AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Microcontroller Abstraction</code> (MCAL) mit oberem <code>Standardized Interface</code> direkt über der <code>ECU-Hardware</code>.</li>\n<li><code>Complex Device Drivers</code> (CDD), vertikal durchgängig von der RTE (<code>AUTOSAR Interface</code>) bis unmittelbar auf die <code>ECU-Hardware</code>.</li>\n<li><strong>Schnittstellentypen laut Legende:</strong></li>\n<li><code>API 1 (RTE relevant)</code>: Gelber Doppelpfeil, markiert standardisierte Aufrufe/Schnittstellen zwischen RTE und BSW-Modulen (OS, Services, Communication).</li>\n<li><code>API 2 &amp; VFB RTE</code>: Blauer Doppelpfeil, markiert AUTOSAR-Interfaces zwischen SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li><code>API 3 (Private Interfaces inside Basic)</code>: Dunkelgrüner Pfeilbus, verbindet interne BSW-Module (Services, Communication, ECU Abstraction, Microcontroller Abstraction) untereinander und mit dem Operating System.</li>\n<li><strong>ECU-Hardware:</strong> Physikalische Basisschicht am unteren Rand des Diagramms.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Interaktion erfolgt über standardisierte Kommunikationspfade:</p>\n<ul class=\"fig-list\">\n<li>Anwendungskomponenten kommunizieren untereinander und mit der BSW ausschließlich über das Virtual Function Bus (VFB)-Konzept via RTE über typisierte Ports/AUTOSAR Interfaces (blaue Pfeile).</li>\n<li>Die RTE leitet Steuerungs- und Datenanforderungen über standardisierte Schnittstellen (gelbe Pfeile) an OS, Services und Communication weiter bzw. über AUTOSAR Interfaces direkt an die ECU Abstraction und Complex Device Drivers.</li>\n<li>Innerhalb der Basis-Software nutzen Module (Services, Communication, ECU Abstraction) standardisierte C-APIs (API 3, grünes Verbindungsgitter), um hardwarenah auf die Microcontroller Abstraction (MCAL) und OS-Dienste zuzugreifen.</li>\n<li>Complex Device Drivers umgehen die Standard-BSW-Schichten und greifen direkt auf die ECU-Hardware zu, behalten jedoch nach oben ein AUTOSAR Interface zur RTE bei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt architektonische Leitfunktion für die BSW- und SW-C-Implementierung:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs dürfen ausschließlich über AUTOSAR Interfaces an die RTE angebunden werden; direkter Durchgriff auf BSW-Module oder Hardware ist unzulässig.</li>\n<li>Hardwareunabhängigkeit der Applikation wird durch die Entkopplung über RTE und Hardwareabstraktionsschichten (ECU Abstraction Layer und MCAL) gewährleistet.</li>\n<li>Hardwarenahe Sonderfunktionen und zeitkritische Zugriffe sind normativ auf Complex Device Drivers (CDD) zu beschränken, die jedoch zur Wahrung der Portabilität von Applikations-SW-Cs über ein AUTOSAR Interface angesprochen werden müssen.</li>\n</ul>"}, {"id": "FIG-17740d40130f0a12", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR-Klassik-Plattform zur Veranschaulichung des Gesamtaufbaus eines Steuergeräts (ECU). Das Diagramm gliedert die Software in drei vertikale Hauptebenen über der zugrundeliegenden ECU-Hardware: die AUTOSAR Software (Anwendungsschicht), die AUTOSAR Runtime Environment (RTE) als Vermittlungsschicht und die Basis-Software (Basic Software, BSW). Linksseitig befindet sich eine Legende zu Komponententypen, Schnittstellenkategorien (Interface, ECU Firmware, Standard Software) und API-Klassifikationen (API 1, API 2, API 3).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Komponenten und Schnittstellenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software (Applikationsebene):</strong> Enthält diskrete Software-Komponenten (SW-Cs) wie <code>Application Software Component</code>, <code>Actuator Software Component</code> und <code>Sensor Software Component</code>. Jede Komponente besitzt an ihrer Unterkante ein <code>AUTOSAR Interface</code>.</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Horizontal durchgängige Middleware-Schicht, die die Anwendungs-Software von der Basis-Software entkoppelt.</li>\n<li><strong>Basic Software (BSW):</strong> Gegliedert in funktionale Säulen/Stapel:</li>\n<li><code>Operating System</code> mit <code>Standardized Interface</code> zur RTE und einer vertikalen <code>Standardized Interface</code>-Flanke zur internen BSW-Interaktion.</li>\n<li><code>Services</code> mit oberem <code>Standardized AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Communication</code> mit oberem und unterem <code>Standardized Interface</code>.</li>\n<li><code>ECU Abstraction</code> mit oberem <code>AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Microcontroller Abstraction</code> (MCAL) mit oberem <code>Standardized Interface</code> direkt über der <code>ECU-Hardware</code>.</li>\n<li><code>Complex Device Drivers</code> (CDD), vertikal durchgängig von der RTE (<code>AUTOSAR Interface</code>) bis unmittelbar auf die <code>ECU-Hardware</code>.</li>\n<li><strong>Schnittstellentypen laut Legende:</strong></li>\n<li><code>API 1 (RTE relevant)</code>: Gelber Doppelpfeil, markiert standardisierte Aufrufe/Schnittstellen zwischen RTE und BSW-Modulen (OS, Services, Communication).</li>\n<li><code>API 2 &amp; VFB RTE</code>: Blauer Doppelpfeil, markiert AUTOSAR-Interfaces zwischen SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li><code>API 3 (Private Interfaces inside Basic)</code>: Dunkelgrüner Pfeilbus, verbindet interne BSW-Module (Services, Communication, ECU Abstraction, Microcontroller Abstraction) untereinander und mit dem Operating System.</li>\n<li><strong>ECU-Hardware:</strong> Physikalische Basisschicht am unteren Rand des Diagramms.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Interaktion erfolgt über standardisierte Kommunikationspfade:</p>\n<ul class=\"fig-list\">\n<li>Anwendungskomponenten kommunizieren untereinander und mit der BSW ausschließlich über das Virtual Function Bus (VFB)-Konzept via RTE über typisierte Ports/AUTOSAR Interfaces (blaue Pfeile).</li>\n<li>Die RTE leitet Steuerungs- und Datenanforderungen über standardisierte Schnittstellen (gelbe Pfeile) an OS, Services und Communication weiter bzw. über AUTOSAR Interfaces direkt an die ECU Abstraction und Complex Device Drivers.</li>\n<li>Innerhalb der Basis-Software nutzen Module (Services, Communication, ECU Abstraction) standardisierte C-APIs (API 3, grünes Verbindungsgitter), um hardwarenah auf die Microcontroller Abstraction (MCAL) und OS-Dienste zuzugreifen.</li>\n<li>Complex Device Drivers umgehen die Standard-BSW-Schichten und greifen direkt auf die ECU-Hardware zu, behalten jedoch nach oben ein AUTOSAR Interface zur RTE bei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt architektonische Leitfunktion für die BSW- und SW-C-Implementierung:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs dürfen ausschließlich über AUTOSAR Interfaces an die RTE angebunden werden; direkter Durchgriff auf BSW-Module oder Hardware ist unzulässig.</li>\n<li>Hardwareunabhängigkeit der Applikation wird durch die Entkopplung über RTE und Hardwareabstraktionsschichten (ECU Abstraction Layer und MCAL) gewährleistet.</li>\n<li>Hardwarenahe Sonderfunktionen und zeitkritische Zugriffe sind normativ auf Complex Device Drivers (CDD) zu beschränken, die jedoch zur Wahrung der Portabilität von Applikations-SW-Cs über ein AUTOSAR Interface angesprochen werden müssen.</li>\n</ul>"}, {"id": "FIG-10d9a98822a1eda0", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR-Klassik-Plattform zur Veranschaulichung des Gesamtaufbaus eines Steuergeräts (ECU). Das Diagramm gliedert die Software in drei vertikale Hauptebenen über der zugrundeliegenden ECU-Hardware: die AUTOSAR Software (Anwendungsschicht), die AUTOSAR Runtime Environment (RTE) als Vermittlungsschicht und die Basis-Software (Basic Software, BSW). Linksseitig befindet sich eine Legende zu Komponententypen, Schnittstellenkategorien (Interface, ECU Firmware, Standard Software) und API-Klassifikationen (API 1, API 2, API 3).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Komponenten und Schnittstellenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software (Applikationsebene):</strong> Enthält diskrete Software-Komponenten (SW-Cs) wie <code>Application Software Component</code>, <code>Actuator Software Component</code> und <code>Sensor Software Component</code>. Jede Komponente besitzt an ihrer Unterkante ein <code>AUTOSAR Interface</code>.</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Horizontal durchgängige Middleware-Schicht, die die Anwendungs-Software von der Basis-Software entkoppelt.</li>\n<li><strong>Basic Software (BSW):</strong> Gegliedert in funktionale Säulen/Stapel:</li>\n<li><code>Operating System</code> mit <code>Standardized Interface</code> zur RTE und einer vertikalen <code>Standardized Interface</code>-Flanke zur internen BSW-Interaktion.</li>\n<li><code>Services</code> mit oberem <code>Standardized AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Communication</code> mit oberem und unterem <code>Standardized Interface</code>.</li>\n<li><code>ECU Abstraction</code> mit oberem <code>AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Microcontroller Abstraction</code> (MCAL) mit oberem <code>Standardized Interface</code> direkt über der <code>ECU-Hardware</code>.</li>\n<li><code>Complex Device Drivers</code> (CDD), vertikal durchgängig von der RTE (<code>AUTOSAR Interface</code>) bis unmittelbar auf die <code>ECU-Hardware</code>.</li>\n<li><strong>Schnittstellentypen laut Legende:</strong></li>\n<li><code>API 1 (RTE relevant)</code>: Gelber Doppelpfeil, markiert standardisierte Aufrufe/Schnittstellen zwischen RTE und BSW-Modulen (OS, Services, Communication).</li>\n<li><code>API 2 &amp; VFB RTE</code>: Blauer Doppelpfeil, markiert AUTOSAR-Interfaces zwischen SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li><code>API 3 (Private Interfaces inside Basic)</code>: Dunkelgrüner Pfeilbus, verbindet interne BSW-Module (Services, Communication, ECU Abstraction, Microcontroller Abstraction) untereinander und mit dem Operating System.</li>\n<li><strong>ECU-Hardware:</strong> Physikalische Basisschicht am unteren Rand des Diagramms.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Interaktion erfolgt über standardisierte Kommunikationspfade:</p>\n<ul class=\"fig-list\">\n<li>Anwendungskomponenten kommunizieren untereinander und mit der BSW ausschließlich über das Virtual Function Bus (VFB)-Konzept via RTE über typisierte Ports/AUTOSAR Interfaces (blaue Pfeile).</li>\n<li>Die RTE leitet Steuerungs- und Datenanforderungen über standardisierte Schnittstellen (gelbe Pfeile) an OS, Services und Communication weiter bzw. über AUTOSAR Interfaces direkt an die ECU Abstraction und Complex Device Drivers.</li>\n<li>Innerhalb der Basis-Software nutzen Module (Services, Communication, ECU Abstraction) standardisierte C-APIs (API 3, grünes Verbindungsgitter), um hardwarenah auf die Microcontroller Abstraction (MCAL) und OS-Dienste zuzugreifen.</li>\n<li>Complex Device Drivers umgehen die Standard-BSW-Schichten und greifen direkt auf die ECU-Hardware zu, behalten jedoch nach oben ein AUTOSAR Interface zur RTE bei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt architektonische Leitfunktion für die BSW- und SW-C-Implementierung:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs dürfen ausschließlich über AUTOSAR Interfaces an die RTE angebunden werden; direkter Durchgriff auf BSW-Module oder Hardware ist unzulässig.</li>\n<li>Hardwareunabhängigkeit der Applikation wird durch die Entkopplung über RTE und Hardwareabstraktionsschichten (ECU Abstraction Layer und MCAL) gewährleistet.</li>\n<li>Hardwarenahe Sonderfunktionen und zeitkritische Zugriffe sind normativ auf Complex Device Drivers (CDD) zu beschränken, die jedoch zur Wahrung der Portabilität von Applikations-SW-Cs über ein AUTOSAR Interface angesprochen werden müssen.</li>\n</ul>"}, {"id": "FIG-b451784848132f88", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR-Klassik-Plattform zur Veranschaulichung des Gesamtaufbaus eines Steuergeräts (ECU). Das Diagramm gliedert die Software in drei vertikale Hauptebenen über der zugrundeliegenden ECU-Hardware: die AUTOSAR Software (Anwendungsschicht), die AUTOSAR Runtime Environment (RTE) als Vermittlungsschicht und die Basis-Software (Basic Software, BSW). Linksseitig befindet sich eine Legende zu Komponententypen, Schnittstellenkategorien (Interface, ECU Firmware, Standard Software) und API-Klassifikationen (API 1, API 2, API 3).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Komponenten und Schnittstellenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Software (Applikationsebene):</strong> Enthält diskrete Software-Komponenten (SW-Cs) wie <code>Application Software Component</code>, <code>Actuator Software Component</code> und <code>Sensor Software Component</code>. Jede Komponente besitzt an ihrer Unterkante ein <code>AUTOSAR Interface</code>.</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Horizontal durchgängige Middleware-Schicht, die die Anwendungs-Software von der Basis-Software entkoppelt.</li>\n<li><strong>Basic Software (BSW):</strong> Gegliedert in funktionale Säulen/Stapel:</li>\n<li><code>Operating System</code> mit <code>Standardized Interface</code> zur RTE und einer vertikalen <code>Standardized Interface</code>-Flanke zur internen BSW-Interaktion.</li>\n<li><code>Services</code> mit oberem <code>Standardized AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Communication</code> mit oberem und unterem <code>Standardized Interface</code>.</li>\n<li><code>ECU Abstraction</code> mit oberem <code>AUTOSAR Interface</code> zur RTE und unterem <code>Standardized Interface</code>.</li>\n<li><code>Microcontroller Abstraction</code> (MCAL) mit oberem <code>Standardized Interface</code> direkt über der <code>ECU-Hardware</code>.</li>\n<li><code>Complex Device Drivers</code> (CDD), vertikal durchgängig von der RTE (<code>AUTOSAR Interface</code>) bis unmittelbar auf die <code>ECU-Hardware</code>.</li>\n<li><strong>Schnittstellentypen laut Legende:</strong></li>\n<li><code>API 1 (RTE relevant)</code>: Gelber Doppelpfeil, markiert standardisierte Aufrufe/Schnittstellen zwischen RTE und BSW-Modulen (OS, Services, Communication).</li>\n<li><code>API 2 &amp; VFB RTE</code>: Blauer Doppelpfeil, markiert AUTOSAR-Interfaces zwischen SW-Cs und RTE sowie zwischen RTE und ECU Abstraction bzw. Complex Device Drivers.</li>\n<li><code>API 3 (Private Interfaces inside Basic)</code>: Dunkelgrüner Pfeilbus, verbindet interne BSW-Module (Services, Communication, ECU Abstraction, Microcontroller Abstraction) untereinander und mit dem Operating System.</li>\n<li><strong>ECU-Hardware:</strong> Physikalische Basisschicht am unteren Rand des Diagramms.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Interaktion erfolgt über standardisierte Kommunikationspfade:</p>\n<ul class=\"fig-list\">\n<li>Anwendungskomponenten kommunizieren untereinander und mit der BSW ausschließlich über das Virtual Function Bus (VFB)-Konzept via RTE über typisierte Ports/AUTOSAR Interfaces (blaue Pfeile).</li>\n<li>Die RTE leitet Steuerungs- und Datenanforderungen über standardisierte Schnittstellen (gelbe Pfeile) an OS, Services und Communication weiter bzw. über AUTOSAR Interfaces direkt an die ECU Abstraction und Complex Device Drivers.</li>\n<li>Innerhalb der Basis-Software nutzen Module (Services, Communication, ECU Abstraction) standardisierte C-APIs (API 3, grünes Verbindungsgitter), um hardwarenah auf die Microcontroller Abstraction (MCAL) und OS-Dienste zuzugreifen.</li>\n<li>Complex Device Drivers umgehen die Standard-BSW-Schichten und greifen direkt auf die ECU-Hardware zu, behalten jedoch nach oben ein AUTOSAR Interface zur RTE bei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt architektonische Leitfunktion für die BSW- und SW-C-Implementierung:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs dürfen ausschließlich über AUTOSAR Interfaces an die RTE angebunden werden; direkter Durchgriff auf BSW-Module oder Hardware ist unzulässig.</li>\n<li>Hardwareunabhängigkeit der Applikation wird durch die Entkopplung über RTE und Hardwareabstraktionsschichten (ECU Abstraction Layer und MCAL) gewährleistet.</li>\n<li>Hardwarenahe Sonderfunktionen und zeitkritische Zugriffe sind normativ auf Complex Device Drivers (CDD) zu beschränken, die jedoch zur Wahrung der Portabilität von Applikations-SW-Cs über ein AUTOSAR Interface angesprochen werden müssen.</li>\n</ul>"}], "trans": [{"from": "FIG-ddf17676f44598a8", "to": "FIG-17740d40130f0a12", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-17740d40130f0a12", "to": "FIG-10d9a98822a1eda0", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-10d9a98822a1eda0", "to": "FIG-b451784848132f88", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
